const User = require('./User');  

class UsersList {
    
    constructor() {
        this.users = [];
    }
    getUsers() {
        return this.users;
    }

    addUser(user) {
        this.users.push(user);
    }
}
const usersList = new UsersList();

// add user example according to user class
//const user = new User(id : 1, email : 'John', 'Doe', 'user1', 'pass1');
const users = [
    { id : 1, email : "user1", password : "pass1" },
    { id : 2, email : "user2", password : "pass2" },
    { id : 3, email : "user3", password : "pass3" }
    ];
usersList.addUser(users[0]);


// Export a singleton instance of the UserList class
module.exports = usersList;
